create database customer_data;
use customer_data;
select * from customer;
--Q1.what is total revenue generated by male vs female customers--

select gender ,sum(purchase_amount) as revenue
from customer
group by gender 

--Q2.which customer used a discount but still  spent more than the average purchase amount?
select customer_id,purchase_amount
from customer
where discount_applied = 'Yes' and 
purchase_amount >= (select AVG (purchase_amount) from customer)
order by purchase_amount desc
limit 1;

--Q3.Which are the top 5 products with the highest average review rating
 select item_purchased,round(AVG(review_rating),2) as rating
 from customer
 group by item_purchased
 order by rating desc
 limit 5;


--Q4.Compare the average purchase amount between standard and express shipping 

select shipping_type,avg(purchase_amount) as avg_purchase_amount
from customer
--Q4.Compare the average purchase amount between standard and express shipping 

select shipping_type,avg(purchase_amount) as avg_purchase_amount
from customer
where shipping_type in ('Standard','Express')
group by shipping_type

--Q.5.Do subscribed customers spend more ? compare average spend total and total revenue between subscribers and non subscribers

select subscription_status, avg(purchase_amount) as average_spend_total,sum(purchase_amount) as total_revenue
from customer
group by subscription_status

